using System;using System.Drawing;using System.Drawing.Drawing2D;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;
namespace IDSketcher{
partial class VectorShape{
 public int[] ContourStarts=new int[0];
 public bool IsClosedVector{get{return Kind=="Polygon"||Kind=="Ellipse"||Kind=="Closed curve"||Kind=="Text"||Kind=="Compound"||Points.Count>=4&&StrokeSession.Distance(Points[0],Points.Last())<.001f;}}
 GraphicsPath CompoundPath(){var path=new GraphicsPath(FillMode.Alternate);for(int i=0;i<ContourStarts.Length;i++){int first=ContourStarts[i],end=i+1<ContourStarts.Length?ContourStarts[i+1]:Points.Count;if(end-first>=3)path.AddPolygon(Points.Skip(first).Take(end-first).ToArray());}return path;}
 public List<List<PointF>> ClosedContours(){var result=new List<List<PointF>>();using(var path=Path()){path.Flatten(null,.1f);var points=path.PathPoints;var types=path.PathTypes;List<PointF> contour=null;for(int i=0;i<points.Length;i++){if((types[i]&7)==0||contour==null){contour=new List<PointF>();result.Add(contour);}if(contour.Count==0||StrokeSession.Distance(contour.Last(),points[i])>.00001f)contour.Add(points[i]);if((types[i]&128)!=0)contour=null;}}foreach(var c in result)if(c.Count>1&&StrokeSession.Distance(c[0],c.Last())<.00001f)c.RemoveAt(c.Count-1);return result.Where(c=>c.Count>=3).ToList();}
 public static VectorShape FromContours(IEnumerable<List<PointF>> contours,VectorShape style){var shape=style.Copy();shape.Kind="Compound";shape.TextContent="";shape.CornerRadius=0;shape.Taper=0;shape.GroupId="";shape.Handles.Clear();shape.Points.Clear();var starts=new List<int>();foreach(var contour in contours.Where(c=>c.Count>=3)){starts.Add(shape.Points.Count);shape.Points.AddRange(contour);}shape.ContourStarts=starts.ToArray();return shape;}
 public void WriteContours(BinaryWriter w){w.Write(ContourStarts.Length);foreach(int start in ContourStarts)w.Write(start);}
 public void ReadContours(BinaryReader r){int count=r.ReadInt32();if(count<0||count>Points.Count/3)throw new InvalidDataException("Invalid compound path.");ContourStarts=new int[count];for(int i=0;i<count;i++){ContourStarts[i]=r.ReadInt32();if(ContourStarts[i]<0||ContourStarts[i]>=Points.Count||i==0&&ContourStarts[i]!=0||i>0&&ContourStarts[i]-ContourStarts[i-1]<3)throw new InvalidDataException("Invalid compound contour.");}if(Kind=="Compound"&&(count==0||Points.Count-ContourStarts[count-1]<3))throw new InvalidDataException("Empty compound path.");}
 public void WriteComplete(BinaryWriter w){Write(w);Fill.Write(w);w.Write(GroupId);WriteText(w);w.Write(CornerRadius);WriteContours(w);}
 public static VectorShape ReadComplete(BinaryReader r){var shape=Read(r,true,true,true);shape.Fill=VectorFillStyle.Read(r);shape.GroupId=r.ReadString();if(shape.GroupId.Length>64)throw new InvalidDataException("Invalid group.");shape.ReadText(r);shape.CornerRadius=r.ReadSingle();if(float.IsNaN(shape.CornerRadius)||shape.CornerRadius<0||shape.CornerRadius>500)throw new InvalidDataException("Invalid radius.");shape.ReadContours(r);return shape;}
}
partial class Canvas{
 void DuplicateDraggedVectors(){var originals=Doc.Selected.Vectors.Where(v=>selectedPaths.Contains(v)).ToArray();var groups=new Dictionary<string,string>();ClearSelectedPaths();foreach(var original in originals){var copy=original.Copy();if(copy.GroupId!=""){string group;if(!groups.TryGetValue(copy.GroupId,out group))groups[copy.GroupId]=group=Guid.NewGuid().ToString("N");copy.GroupId=group;}Doc.Selected.Vectors.Add(copy);AddSelectedPath(copy);if(original==selectedVector)selectedVector=copy;}selectedPoints.Clear();if(VectorSelected!=null)VectorSelected();}
 public void TestDefaultBoxAndDuplicate(){CancelVector();VectorMode="Line";Zoom=1;Offset=PointF.Empty;TestDrag(new Point(80,100),new Point(200,100));VectorMode="Select/edit";TestDrag(new Point(40,60),new Point(240,140));if(selectedPaths.Count!=1)throw new Exception("Default drag box selection");var original=Doc.Selected.Vectors.Last();var start=original.Points.ToArray();PickVector(new PointF(140,100),Keys.Alt);VectorMove(new PointF(180,140));VectorUp(new PointF(180,140));if(Doc.Selected.Vectors.Count!=2||!original.Points.SequenceEqual(start)||selectedVector.Points[0]!=new PointF(120,140))throw new Exception("Alt drag duplicate preserves original");PickVector(new PointF(180,140),Keys.Alt);VectorUp(new PointF(180,140));if(Doc.Selected.Vectors.Count!=2)throw new Exception("Alt click must not duplicate");}
 string pastedPayload;int pasteCount;
 public string CopyVectorPayload(){if(Doc==null||!Doc.Selected.IsVector)return null;var shapes=Doc.Selected.Vectors.Where(v=>selectedPaths.Contains(v)).ToArray();if(shapes.Length==0)return null;using(var stream=new MemoryStream())using(var writer=new BinaryWriter(stream)){writer.Write("IDeaSKETCHER VECTORS 1");writer.Write(shapes.Length);foreach(var shape in shapes)shape.WriteComplete(writer);return Convert.ToBase64String(stream.ToArray());}}
 public bool PasteVectorPayload(string payload){if(Doc==null||!Doc.Selected.IsVector||Doc.Selected.IsLocked||!Doc.Selected.Visible||string.IsNullOrEmpty(payload))return false;if(payload.Length>32000000)throw new InvalidDataException("Clipboard selection is too large.");var shapes=new List<VectorShape>();using(var stream=new MemoryStream(Convert.FromBase64String(payload)))using(var reader=new BinaryReader(stream)){if(reader.ReadString()!="IDeaSKETCHER VECTORS 1")return false;int count=reader.ReadInt32();if(count<1||count+Doc.Selected.Vectors.Count>10000)throw new InvalidDataException("Too many clipboard vectors.");for(int i=0;i<count;i++)shapes.Add(VectorShape.ReadComplete(reader));if(stream.Position!=stream.Length)throw new InvalidDataException("Invalid vector clipboard data.");}
  if(pastedPayload!=payload){pastedPayload=payload;pasteCount=0;}float offset=20*++pasteCount;var groups=new Dictionary<string,string>();foreach(var shape in shapes){for(int i=0;i<shape.Points.Count;i++)shape.Points[i]=new PointF(shape.Points[i].X+offset,shape.Points[i].Y+offset);if(shape.GroupId!=""){string group;if(!groups.TryGetValue(shape.GroupId,out group))groups[shape.GroupId]=group=Guid.NewGuid().ToString("N");shape.GroupId=group;}}
  EndStroke();if(BeforeStroke!=null)BeforeStroke();ClearSelectedPaths();foreach(var shape in shapes){Doc.Selected.Vectors.Add(shape);AddSelectedPath(shape);}selectedVector=shapes.Last();selectedPoints.Clear();Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();if(VectorSelected!=null)VectorSelected();NotifyPointSelection();Invalidate();return true;
 }
 public bool CanCombineClosed{get{return Doc!=null&&Doc.Selected.IsVector&&!Doc.Selected.IsLocked&&Doc.Selected.Visible&&selectedPaths.Count>=2&&selectedPaths.All(s=>s.IsClosedVector);}}
 void ReplaceCombinedVectors(List<VectorShape> originals,List<VectorShape> results){if(results.Any(s=>s.Points.Count>10000)||Doc.Selected.Vectors.Count-originals.Count+results.Count>10000)throw new InvalidOperationException("The result has too many vector points.");int at=Doc.Selected.Vectors.IndexOf(originals.Last());at-=Doc.Selected.Vectors.Take(at).Count(v=>originals.Contains(v));EndStroke();if(BeforeStroke!=null)BeforeStroke();foreach(var shape in originals)Doc.Selected.Vectors.Remove(shape);ClearSelectedPaths();foreach(var shape in results){Doc.Selected.Vectors.Insert(at++,shape);AddSelectedPath(shape);}selectedVector=results.LastOrDefault();selectedPoints.Clear();Doc.Selected.InvalidateVectors();if(AfterStroke!=null)AfterStroke();if(selectedVector!=null&&VectorSelected!=null)VectorSelected();NotifyPointSelection();Invalidate();}
 public void JoinCompoundVectors(){if(!CanCombineClosed)return;var originals=Doc.Selected.Vectors.Where(v=>selectedPaths.Contains(v)).ToList();var source=selectionOrder.FirstOrDefault(v=>originals.Contains(v))??originals[0];var compound=VectorShape.FromContours(originals.SelectMany(v=>v.ClosedContours()),source);if(compound.Points.Count>=3)ReplaceCombinedVectors(originals,new List<VectorShape>{compound});}
}
partial class Studio{
 public void TestBoxDuplicateShortcuts(){previewing=true;Show();SetDocument(new Document("A4",100),null);canvas.Focus();if(!HandleSelectionKeys(Keys.B)||canvas.SelectionMode!="Box selection")throw new Exception("Pixel B shortcut");AddTypedLayer(true);canvas.Focus();if(!HandleSelectionKeys(Keys.B)||!canvas.VectorBoxMode)throw new Exception("Vector B shortcut");vectorPicker.PerformClick();int history=undo.Count;canvas.TestDefaultBoxAndDuplicate();if(undo.Count!=history+2)throw new Exception("Duplicate single undo");Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=1)throw new Exception("Duplicate undo");Travel(redo,undo);if(canvas.Doc.Selected.Vectors.Count!=2)throw new Exception("Duplicate redo");dirty=false;}
 const string VectorClipboardFormat="IDeaSKETCHER.VectorPaths.v1";Func<string> readVectorClipboard=delegate{return Clipboard.ContainsData(VectorClipboardFormat)?Clipboard.GetData(VectorClipboardFormat) as string:null;};Action<string> writeVectorClipboard=delegate(string value){Clipboard.SetData(VectorClipboardFormat,value);};
 bool HandleVectorClipboardKeys(Keys key){if(ActiveControl is TextBoxBase||ActiveControl is NumericUpDown||ActiveControl is ComboBox||canvas.Doc==null||!canvas.Doc.Selected.IsVector)return false;try{if(key==(Keys.Control|Keys.C)){string payload=canvas.CopyVectorPayload();if(payload!=null)writeVectorClipboard(payload);return true;}if(key==(Keys.Control|Keys.V)){string payload=readVectorClipboard();if(payload!=null){canvas.AcceptVectorDraft();vectorMode.SelectedItem="Select/edit";canvas.SetSelectionMode("Draw");canvas.PasteVectorPayload(payload);canvas.Focus();}return true;}if(key==(Keys.Control|Keys.J)){canvas.JoinCompoundVectors();return true;}}catch(Exception error){MessageBox.Show(this,error.Message,"VECTOR OPERATION");return true;}return false;}
}
}
